data class UiState(val items: List<Item> = emptyList(), val loading: Boolean = false)
sealed interface Intent {
    data object Refresh : Intent
    data class Loaded(val items: List<Item>) : Intent
}
class FeedViewModel : ViewModel() {
    private val _state = MutableStateFlow(UiState())
    val state: StateFlow<UiState> = _state.asStateFlow()
    fun onIntent(intent: Intent) = _state.update { s -> reduce(s, intent) }
    private fun reduce(s: UiState, i: Intent): UiState = when (i) {
        is Intent.Refresh -> s.copy(loading = true)
        is Intent.Loaded  -> s.copy(items = i.items, loading = false)
    }
}
